import{_ as l,l as i,o as e,c as s,v as t,p as n,x as o,d,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"答案抽取与归一化","description":"","frontmatter":{"title":"答案抽取与归一化","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/answer-extraction.md","filePath":"llm/answer-extraction.md","lastUpdated":1789023840000}'),E={name:"llm/answer-extraction.md"};function h(m,a,_,A,f,B){const r=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="答案抽取与归一化" tabindex="-1">答案抽取与归一化 <a class="header-anchor" href="#答案抽取与归一化" aria-label="Permalink to &quot;答案抽取与归一化&quot;">​</a></h1><div class="epigraph"><p>模型写对了推导，抽取器没认出最后一行的数，这道题在榜上是错的。评测的是管道，不只是网络。</p><footer>—— 对照 GSM8K / MATH 的数字与 LaTeX 归一化；Minerva 对等价式的处理</footer></div><p><a href="/llm/prompt-format-sensitivity">上一课</a>说明包装能改分。生成式协议还有更硬的一层：从自由文本里抽出可比较的答案。本课写抽取与归一化。缺口是把「生成质量」从「解析器质量」里拆开。后课 <a href="/llm/pass-at-k">pass@k</a> 默认：代码评测的「对」来自测试执行，数学评测的「对」来自抽取器。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Cobbe 的 GSM8K、Hendrycks 的 MATH 允许长推理，金标却是一个数或短表达式。模型若把答案写在「因此」之后而不是 <code>####</code> 之后，严格字符串匹配会判错。反过来，模型乱写一通但最后一行碰巧抄对数字，会判对——抽取器在奖励格式，惩罚健谈但正确的推导。</p><p>归一化同样改分：<code>1/2</code> 与 <code>0.5</code>、<code>$\\\\frac{1}{2}$</code> 与 <code>0.5</code>、单位、千分位逗号、中文「百分之十二」。Lewkowycz 等 Minerva 用符号等价（解析后比较）而不是字面匹配，数学分才接近「算对了」。未声明抽取器的 MATH 分不可复现。</p><p><span class="marginnote">选择题的「抽第一个字母」也是抽取器。它会把「答案是 B，但更完整地说是 C」判成 B。协议必须规定冲突时以谁为准。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>管道：生成 → 裁剪停止符 → 正则或语法抽取候选 → 归一化（去空白、统一减号、解析 LaTeX）→ 与金标比较。数学优先符号等价；数字允许相对容差（百分数题要声明）。抽不到则记错，不要回退到「全文是否包含金标子串」——那会把解析过程里出现的中间数当成最终答案。</p><p>报告应附抽取失败率。失败率高时，先修提示（「把最终答案放在 \\boxed{}」）再谈模型；否则你在用提示补偿解析器。</p>',10)),(e(),n(p,null,{default:o(()=>[c(r,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20GEN%5B%22%E7%94%9F%E6%88%90%E6%96%87%E6%9C%AC%22%5D%20--%3E%20CUT%5B%22%E5%81%9C%E6%AD%A2%E4%B8%8E%E8%A3%81%E5%89%AA%22%5D%0A%20%20CUT%20--%3E%20EX%5B%22%E6%8A%BD%E5%8F%96%E5%80%99%E9%80%89%22%5D%0A%20%20EX%20--%3E%20NORM%5B%22%E5%BD%92%E4%B8%80%E5%8C%96%20%2F%20%E7%AC%A6%E5%8F%B7%E7%AD%89%E4%BB%B7%22%5D%0A%20%20NORM%20--%3E%20CMP%5B%22%E5%AF%B9%E9%87%91%E6%A0%87%22%5D%0A%20%20EX%20--%3E%20MISS%5B%22%E6%8A%BD%E5%8F%96%E5%A4%B1%E8%B4%A5%20%3D%20%E9%94%99%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>自回归没有「答案槽」这个变量，槽是评测脚本事后定义的。抽取规则等于在定义任务：GSM8K 的 <code>####</code> 是训练时就对齐过的槽；换一种槽，能力数字改的是接口，不是权重。符号等价把「同一数学对象」的多种表面形式收成一类，减小假阴性，但解析器自身会误读宏包与省略括号，引入假阳性。必须版本化抽取代码。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>开放写作没有金标槽，抽取器不适用，应走后课裁判或人评。代码用单测，不要对源代码做字符串匹配。下一课 pass@k 处理「对一次算会」的抽样统计，抽取/执行仍在内层。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>生成式准确率 = 模型 × 抽取 × 归一化；三者必须版本化。</li><li>数学用符号等价，避免字面匹配惩罚正确推导。</li><li>抽取失败应记错并单列失败率，禁止模糊子串匹配当主指标。</li><li>出处：Cobbe 等 GSM8K；Hendrycks 等 MATH；Lewkowycz 等 Minerva。</li></ul>',6))])}const b=l(E,[["render",h]]);export{u as __pageData,b as default};
